25	
26	        $enrollment = Enrollment::firstOrCreate([
27	            'user_id'   => $request->user()->id,
28	            'course_id' => $courseId,
29	        ]);
30	
31	        $course->increment('students_count');
32	
33	        return response()->json($enrollment, 201);
34	    }
35	
36	    // Update course progress manual
37	    public function updateProgress(Request $request, $courseId)
38	    {
39	        $data = $request->validate(['progress' => 'required|integer|min:0|max:100']);
40	
41	        $enrollment = Enrollment::where('user_id', $request->user()->id)
42	            ->where('course_id', $courseId)
43	            ->firstOrFail();
44	
45	        $enrollment->update(['progress' => $data['progress']]);
46	
47	        return response()->json($enrollment);
48	    }
49	
50	    // Complete a module and recalculate progress
51	    public function completeModule(Request $request, $courseId)
52	    {
53	        $request->validate([
54	            'module_id' => 'required|exists:modules,id'
55	        ]);
56	        
57	        $moduleId = (int) $request->module_id;
58	
59	        // Security: Ensure module belongs to the course
60	        $module = \App\Models\Module::where('id', $moduleId)
61	            ->where('course_id', $courseId)
62	            ->firstOrFail();
63	
64	        $enrollment = Enrollment::where('user_id', $request->user()->id)
65	            ->where('course_id', $courseId)
66	            ->firstOrFail();
67	
68	        $completed = $enrollment->completed_modules ?? [];
69	
70	        if (!in_array($moduleId, $completed)) {
71	            $completed[] = $moduleId;
72	            $enrollment->completed_modules = $completed;
73	            
74	            // Recalculate progress percentage accurately
75	            $totalModules = \App\Models\Module::where('course_id', $courseId)->count();
76	            if ($totalModules > 0) {
77	                // Ensure we don't exceed 100% and round down to nearest int
78	                $enrollment->progress = min(100, (int) (count($completed) / $totalModules * 100));
79	            }
80	            
81	            $enrollment->save();
82	        }
83	
84	        return response()->json($enrollment->load('course.modules'));
85	    }
