34	class ErrorBoundary extends React.Component {
35	  constructor(props) {
36	    super(props);
37	    this.state = { hasError: false };
38	  }
39	  static getDerivedStateFromError(error) { return { hasError: true }; }
40	  componentDidCatch(error, errorInfo) { console.error("Global Error:", error, errorInfo); }
41	  render() {
42	    if (this.state.hasError) {
43	      return (
44	        <div style={{ height: '100vh', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', background: '#030308', color: '#fff', textAlign: 'center', padding: '2rem' }}>
