75	        <Route path="/mes-cours"   element={<DashboardLayout><MesCours /></DashboardLayout>} />
76	        <Route path="/favoris"     element={<DashboardLayout><Favoris /></DashboardLayout>} />
77	        <Route path="/certificats" element={<DashboardLayout><Certificats /></DashboardLayout>} />
78	        <Route path="/profile"     element={<DashboardLayout><Profile /></DashboardLayout>} />
79	        <Route path="/settings"    element={<DashboardLayout><Settings /></DashboardLayout>} />
80	        <Route path="/course/:id"  element={<DashboardLayout><CoursePlayer /></DashboardLayout>} />
81	        <Route path="/quiz/:id"    element={<DashboardLayout><Quiz /></DashboardLayout>} />
82	        <Route path="/admin/*"     element={<AdminRoute><AdminPanel /></AdminRoute>} />
83	        <Route path="/admin"       element={<AdminRoute><AdminPanel /></AdminRoute>} />
84	        <Route path="/catalogue"   element={<DashboardLayout><Catalogue /></DashboardLayout>} />
85	        <Route path="/communaute"  element={<DashboardLayout><Community /></DashboardLayout>} />
86	        <Route path="/calendrier"  element={<DashboardLayout><CalendarPage /></DashboardLayout>} />
87	        
88	        {/* Fallback */}
89	        <Route path="*" element={<Navigate to="/" replace />} />
