import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Users, BookOpen, MessageSquare, TrendingUp,
  Trash2, Plus, Edit, X, Lock,
  BarChart3, CheckCircle2, Search,
  RefreshCw, Award, Shield, Film, ChevronDown, ChevronUp
} from 'lucide-react';
import api from '../services/api';
import AdminLayout from '../layouts/AdminLayout';
import { useLocation } from 'react-router-dom';

const AdminPanel = () => {
  const location = useLocation();
  const [activeTab, setActiveTab] = useState('Dashboard');
  const [systemSettings, setSystemSettings] = useState({
    maintenance_mode: '0',
    allow_registrations: '1',
    auto_emails: '1'
  });

  const fetchSettings = async () => {
    try {
      const res = await api.get('/admin/settings');
      setSystemSettings(res.data);
    } catch (err) {
      console.error("Failed to load settings");
    }
  };

  const handleSaveSettings = async () => {
    try {
      await api.post('/admin/settings', systemSettings);
      showToast('Configuration système synchronisée en temps réel !');
    } catch (err) {
      showToast('Échec de la synchronisation', 'error');
    }
  };

  useEffect(() => {
    const path = location.pathname;
    if (path === '/admin/courses') setActiveTab('Courses');
    else if (path === '/admin/users') setActiveTab('Students');
    else if (path === '/admin/settings') setActiveTab('Settings');
    else setActiveTab('Dashboard');
  }, [location.pathname]);

  const [stats, setStats] = useState(null);
  const [courses, setCourses] = useState([]);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  const [modalType, setModalType] = useState(null);
  const [selectedCourse, setSelectedCourse] = useState(null);
  const [newCourse, setNewCourse] = useState({ title: '', description: '', thumbnail: '', price: 0 });
  const [editCourse, setEditCourse] = useState({ title: '', description: '', thumbnail: '', price: 0 });
  const [toast, setToast] = useState(null);

  const showToast = (msg, type = 'success') => {

content.content:
60	  const showToast = (msg, type = 'success') => {
61	    setToast({ msg, type });
62	    setTimeout(() => setToast(null), 3500);
63	  };
64	
65	  useEffect(() => { 
66	    fetchData();
67	    fetchSettings();
68	  }, []);
69	
70	  const fetchData = async () => {
71	    setLoading(true);
72	    try {
73	      const [sRes, cRes, uRes] = await Promise.all([
74	        api.get('/admin/stats'),
75	        api.get('/admin/courses'),
76	        api.get('/admin/users')
77	      ]);
78	      setStats(sRes.data);
79	      setCourses(cRes.data);
80	      setUsers(uRes.data);
81	    } catch (err) {
82	      showToast('Erreur de synchronisation.', 'error');
83	    } finally {
84	      setLoading(false);
85	    }
86	  };
87	
88	  const handleCreateCourse = async (e) => {
89	    e.preventDefault();
90	    try {
91	      await api.post('/courses', newCourse);
92	      setModalType(null);
93	      setNewCourse({ title: '', description: '', thumbnail: '', price: 0 });
94	      fetchData();
95	      showToast('Cours publié avec succès !');
96	    } catch (err) {
97	      showToast("Erreur de publication", 'error');
98	    }
99	  };
100	
101	  const handleEditCourse = async (e) => {
102	    e.preventDefault();
103	    if (!selectedCourse) return;
104	    try {
105	      await api.put(`/courses/${selectedCourse.id}`, editCourse);
106	      setModalType(null);
107	      fetchData();
108	      showToast('Modifications enregistrées.');
109	    } catch (err) {
110	      showToast("Mise à jour échouée", 'error');
111	    }
112	  };
113	
114	  const handleToggleAdmin = async (userId) => {
115	    try {
116	      const res = await api.post(`/admin/users/${userId}/toggle-admin`);
117	      showToast(res.data.message);
118	      fetchData();
119	    } catch (err) {
120	      showToast('Droit de modification refusé.', 'error');
121	    }
122	  };
123	
124	  const filteredCourses = useMemo(() =>
125	    courses.filter(c => c.title.toLowerCase().includes(searchQuery.toLowerCase())),
126	    [courses, searchQuery]
127	  );
128	
129	  const filteredUsers = useMemo(() => {
130	    const currentUser = JSON.parse(localStorage.getItem('user') || '{}');
131	    return users.filter(u =>
132	      u.id !== currentUser.id && (
133	        u.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
134	        u.email.toLowerCase().includes(searchQuery.toLowerCase())
135	      )
136	    );
137	  }, [users, searchQuery]);
138	
139	  const chartData = stats?.monthly_registrations || [];
140	  const topCourses = stats?.top_courses || [];
141	
142	  return (
143	    <AdminLayout>
144	      <div className="admin-content-scroller" style={{ padding: '2rem 2.5rem', flex: 1, overflowY: 'auto' }}>
145	        
146	        {/* Modern Header - Adjusted sizing */}
147	        <div className="governance-header">
148	          <div>
149	            <div className="security-badge">
150	              <Lock size={12} /> SYSTÈME SÉCURISÉ
151	            </div>
152	            <h1 className="brand-font" style={{ fontSize: '2.4rem', margin: '0.75rem 0' }}>Centre de Gestion</h1>
153	            <p style={{ color: 'var(--text-muted)', fontSize: '0.95rem' }}>Gérez les formations et surveillez la croissance de VibeAcademy.</p>
154	          </div>
155	          <div style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
156	            <div className="admin-search-bar" style={{ width: 280 }}>
157	              <Search size={16} />
158	              <input type="text" placeholder="Rechercher..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} />
159	            </div>
160	            <button className="btn-pro btn-pro-primary" onClick={() => setModalType('course')}>
161	              <Plus size={18} /> Nouveau Cours
162	            </button>
163	          </div>
164	        </div>
165	
166	        {/* Tab UI - Integrated touch */}
167	        <div className="admin-tab-nav" style={{ marginBottom: '3rem' }}>
168	          {[
169	            { id: 'Dashboard', icon: BarChart3, label: 'Performance' },
170	            { id: 'Courses', icon: BookOpen, label: 'Catalogue' },
171	            { id: 'Students', icon: Users, label: 'Apprenants' },
172	            { id: 'Settings', icon: Shield, label: 'Système' }
173	          ].map(tab => (
174	            <button key={tab.id} className={`admin-tab-item ${activeTab === tab.id ? 'active' : ''}`} onClick={() => setActiveTab(tab.id)}>
175	              <tab.icon size={16} /> {tab.label}
176	            </button>
177	          ))}
178	        </div>
179	
180	        {loading ? (
181	          <div className="flex-center" style={{ flexDirection: 'column', gap: '1.5rem', height: '40vh' }}>
182	            <RefreshCw size={40} className="spin-slow" color="#7000ff" />
183	            <p className="brand-font" style={{ color: 'var(--text-muted)' }}>Synchronisation en cours...</p>
184	          </div>
185	        ) : (
186	          <AnimatePresence mode="wait">
187	            
188	            {activeTab === 'Dashboard' && (
189	              <motion.div key="dash" initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}>
190	                <div className="stat-grid">
191	                  <StatCard label="Étudiants" value={stats?.users || 0} icon={<Users size={22}/>} color="#a78bfa" />
192	                  <StatCard label="Formations" value={stats?.courses || 0} icon={<BookOpen size={22}/>} color="#0bd1ff" />
193	                  <StatCard label="Réussite" value={stats?.completion_rate || 0} unit="%" icon={<Award size={22}/>} color="#4ade80" />
194	                  <StatCard label="Retours" value={stats?.comments || 0} icon={<MessageSquare size={22}/>} color="#f59e0b" />
195	                </div>
196	
197	                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))', gap: '2rem' }}>
198	                  <div className="glass-card" style={{ padding: '2rem' }}>
199	                     <h3 className="brand-font" style={{ marginBottom: '2rem', fontSize: '1.2rem' }}>Inscriptions Mensuelles</h3>
200	                     <div style={{ display: 'flex', alignItems: 'flex-end', gap: '1rem', height: '180px', paddingBottom: '0.5rem' }}>
201	                        {chartData.map((d, i) => {
202	                           const maxCount = Math.max(...chartData.map(x => x.count)) || 1;
203	                           const heightPercent = (d.count / maxCount) * 100;
204	                           return (
205	                             <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '0.8rem', height: '100%' }}>
206	                                <div style={{ 
207	                                   width: '100%', 
208	                                   flex: 1, 
209	                                   background: 'rgba(255,255,255,0.02)', 
210	                                   borderRadius: '10px', 
211	                                   position: 'relative', 
212	                                   overflow: 'hidden',
213	                                   display: 'flex',
214	                                   alignItems: 'flex-end',
215	                                   border: '1px solid rgba(255,255,255,0.03)'
216	                                }}>
217	                                   {/* The visible bar */}
218	                                   <motion.div 
219	                                     initial={{ height: 0 }} 
220	                                     animate={{ height: `${Math.max(heightPercent, d.count > 0 ? 5 : 2)}%` }}
221	                                     style={{ 
222	                                       width: '100%', 
223	                                       background: d.count > 0 ? 'var(--gradient-magic)' : 'rgba(112,0,255,0.08)', 
224	                                       borderRadius: '6px',
225	                                       boxShadow: d.count > 0 ? '0 0 15px rgba(112,0,255,0.3)' : 'none'
226	                                     }}
227	                                   />
228	                                </div>
229	                                <span style={{ fontSize: '0.65rem', color: 'var(--text-muted)', fontWeight: 800, textTransform: 'uppercase' }}>{d.month}</span>
230	                             </div>
231	                           );
232	                        })}
233	                     </div>
234	                  </div>
235	                  <div className="glass-card" style={{ padding: '2rem' }}>
236	                     <h3 className="brand-font" style={{ marginBottom: '2rem', fontSize: '1.2rem' }}>Formations Populaires</h3>
237	                     <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
238	                        {topCourses.length === 0 ? (
239	                           <p style={{ color: 'var(--text-muted)', textAlign: 'center', padding: '2rem' }}>Aucune donnée d'inscription disponible.</p>
