247	                                      <span style={{ fontWeight: 700, fontSize: '0.85rem', color: 'var(--text-main)' }}>{c.title}</span>
248	                                      <span style={{ color: '#a78bfa', fontWeight: 800, fontSize: '0.8rem' }}>{c.enrollments_count} inscrit{c.enrollments_count > 1 ? 's' : ''}</span>
249	                                   </div>
250	                                   <div style={{ height: '6px', background: 'rgba(255,255,255,0.05)', borderRadius: '100px', overflow: 'hidden' }}>
251	                                      <motion.div 
252	                                        initial={{ width: 0 }} 
253	                                        animate={{ width: `${widthPercent || 2}%` }} // Minimal 2% width to show the bar exists
254	                                        style={{ height: '100%', background: 'var(--gradient-cyber)', borderRadius: '100px' }} 
255	                                      />
256	                                   </div>
257	                                </div>
258	                              );
259	                           })
260	                        )}
261	                     </div>
262	                  </div>
263	                </div>
264	              </motion.div>
