271	                      <img src={c.thumbnail} alt="" style={{ width: 80, height: 50, borderRadius: '10px', objectFit: 'cover' }} />
272	                      <div>
273	                         <h4 style={{ fontWeight: 800 }}>{c.title}</h4>
274	                         <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{c.price > 0 ? `${c.price}€` : 'Gratuit'}</span>
275	                      </div>
276	                      <div style={{ fontSize: '0.9rem', fontWeight: 700, color: '#a78bfa' }}>{c.enrollments_count} Éléves</div>
277	                      <div style={{ color: '#4ade80', fontSize: '0.65rem', padding: '0.4rem', background: 'rgba(74,222,128,0.1)', borderRadius: '8px', textAlign: 'center', fontWeight: 800 }}>ACTIF</div>
278	                      <div style={{ display: 'flex', gap: '0.5rem', justifyContent: 'flex-end' }}>
279	                         <button className="admin-action-btn" onClick={() => { setSelectedCourse(c); setEditCourse({title: c.title, description: c.description, thumbnail: c.thumbnail, price: c.price}); setModalType('editCourse'); }}><Edit size={18} /></button>
280	                         <button className="admin-action-btn danger" onClick={() => api.delete(`/admin/courses/${c.id}`).then(fetchData)}><Trash2 size={18} /></button>
281	                      </div>
282	                   </div>
283	                 ))}
284	              </motion.div>
285	            )}
286	
287	            {activeTab === 'Students' && (
288	              <motion.div key="users" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
289	                 {filteredUsers.map(u => (
290	                   <div key={u.id} className="asset-row" style={{ gridTemplateColumns: '50px 1fr 180px 100px 100px' }}>
291	                      <div style={{ width: 44, height: 44, borderRadius: '12px', background: u.is_admin ? 'rgba(112,0,255,0.1)' : 'var(--bg-tertiary)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 800, color: u.is_admin ? '#a78bfa' : '#fff' }}>{u.name[0]}</div>
292	                      <div>
293	                         <h4 style={{ fontWeight: 700 }}>{u.name}</h4>
294	                         <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{u.email}</p>
