41	        $course = Course::create([
42	            'title'       => $data['title'],
43	            'description' => $data['description'],
44	            'thumbnail'   => $data['thumbnail'],
45	            'price'       => $data['price'] ?? 0,
46	            'user_id'     => $request->user()->id,
47	        ]);
48	
49	        return response()->json($course->load('instructor', 'modules'), 201);
